(() => {
const COPY={"subtitle": ["한 번의 스캔이, 더 안심되는 하루로.", "A little scan. A clearer picture of their wellbeing.", "Một lần quét, thêm an tâm mỗi ngày."], "dashboard": ["대시보드", "Dashboard", "Tổng quan"], "records": ["측정 기록", "Records", "Lịch sử đo"], "guide": ["케어 가이드", "Care guide", "Hướng dẫn"], "scanner": ["스캐너 연결", "Scanner", "Máy quét"], "local": ["이 브라우저에 저장", "Stored in this browser", "Lưu trong trình duyệt này"], "localNote": ["기기·브라우저가 바뀌면 기록이 공유되지 않습니다. 백업을 내려받아 보관하세요.", "Records are not shared across devices or browsers. Download a backup to keep them safe.", "Dữ liệu không được đồng bộ giữa thiết bị hoặc trình duyệt. Hãy tải bản sao lưu để lưu giữ."], "pet": ["내 반려견", "My dog", "Chó của tôi"], "selectPet": ["반려견을 등록해 주세요", "Add your dog to begin", "Thêm chó để bắt đầu"], "addPet": ["반려견 추가", "Add dog", "Thêm chó"], "editPet": ["프로필 설정", "Edit profile", "Sửa hồ sơ"], "connect": ["스캐너 연결", "Connect scanner", "Kết nối máy quét"], "disconnect": ["연결 해제", "Disconnect", "Ngắt kết nối"], "connected": ["연결됨", "Connected", "Đã kết nối"], "offline": ["연결 대기", "Not connected", "Chưa kết nối"], "demo": ["데모 보기", "View demo", "Xem thử"], "demoExit": ["실제 기록으로 돌아가기", "Return to real records", "Về dữ liệu thực"], "demoNote": ["미리보기 · 모든 이름과 수치는 예시이며 실측 기록이 아닙니다.", "DEMO · All names and readings are examples, not real measurements.", "XEM THỬ · Tên và số liệu đều là ví dụ, không phải phép đo thực."], "latest": ["최근 측정", "Latest reading", "Lần đo gần nhất"], "fresh": ["방금 수신", "Just received", "Vừa nhận"], "noReading": ["아직 측정 기록이 없어요", "No readings yet", "Chưa có kết quả đo"], "chip": ["피하 칩", "Subcutaneous chip", "Vi mạch dưới da"], "rectal": ["직장 체온 · 직접 입력", "Rectal · manual entry", "Trực tràng · nhập tay"], "manual": ["직접 입력", "Manual entry", "Nhập thủ công"], "ble": ["스캐너 수신", "Scanner reading", "Dữ liệu máy quét"], "reference": ["성견 직장 체온 참고 범위", "Adult dog rectal reference range", "Khoảng tham chiếu nhiệt độ trực tràng chó trưởng thành"], "range": ["37.5–39.2℃", "37.5–39.2°C", "37,5–39,2°C"], "baseline": ["평소 피하 기준체온", "Usual chip baseline", "Nhiệt độ vi mạch cơ sở"], "notSet": ["미설정", "Not set", "Chưa đặt"], "methodNote": ["피하 온도는 직장 체온과 다릅니다. 직장 기준으로 바로 정상·이상을 판정하지 않습니다.", "Subcutaneous and rectal readings differ. The rectal reference cannot directly diagnose a chip reading.", "Nhiệt độ dưới da khác nhiệt độ trực tràng. Không dùng trực tiếp khoảng trực tràng để chẩn đoán số đo vi mạch."], "healthCheck": ["지금 확인할 것", "What to check now", "Cần kiểm tra ngay"], "none": ["측정을 시작해 보세요", "Start with a reading", "Bắt đầu đo"], "noneBody": ["반려견을 등록하고 스캐너를 연결하세요. 직장 체온을 직접 입력해 기록할 수도 있습니다.", "Add your dog and connect the scanner, or enter a rectal reading manually.", "Thêm chó và kết nối máy quét, hoặc nhập nhiệt độ trực tràng thủ công."], "sensor": ["센서 범위 밖 · 측정 확인", "Outside sensor range", "Ngoài dải cảm biến"], "sensorBody": ["제품 표기 측정 범위는 30–45℃입니다. 삽입되지 않은 테스트 칩·접촉 상태·환경을 확인하세요. 개체의 저체온으로 단정하지 않으며 자동 저장·분석에서 제외합니다.", "The specified sensor range is 30–45°C. Check for an unimplanted test chip, positioning or environmental effects. This alone does not establish hypothermia and is excluded from automatic saving and analysis.", "Dải cảm biến công bố là 30–45°C. Kiểm tra vi mạch thử chưa cấy, vị trí hoặc môi trường. Không kết luận hạ thân nhiệt chỉ từ số đo này; không tự lưu hoặc phân tích."], "chipNoBase": ["피하 측정 · 기준체온 필요", "Chip reading · baseline needed", "Đo dưới da · cần mức cơ sở"], "chipNoBaseBody": ["피하 수치만으로 정상 여부를 확정할 수 없습니다. 건강하고 안정된 날의 개인 기준을 설정하고, 이상이 의심되면 직장 체온과 증상을 함께 확인하세요.", "A chip reading alone cannot establish normal health. Set an individual baseline from a healthy, resting day; confirm concerns with a rectal reading and symptoms.", "Không thể xác định bình thường chỉ từ số đo vi mạch. Đặt mức cơ sở khi khỏe và nghỉ ngơi; nếu nghi bất thường, kiểm tra nhiệt độ trực tràng và triệu chứng."], "chipStable": ["설정한 기준 부근", "Near the chosen baseline", "Gần mức cơ sở đã đặt"], "chipStableBody": ["설정한 개인 기준에서 큰 이탈은 보이지 않습니다. 이 결과는 건강함을 보장하지 않으며, 증상이 있으면 수치와 관계없이 진료가 필요합니다.", "No large deviation from your chosen baseline. This does not prove good health; symptoms still need veterinary assessment.", "Chưa thấy lệch lớn so với mức cơ sở đã đặt. Điều này không đảm bảo sức khỏe; nếu có triệu chứng vẫn cần khám thú y."], "chipShift": ["평소와 다른 변화", "A change from the baseline", "Thay đổi so với cơ sở"], "chipShiftBody": ["사용자가 설정한 변화 기준을 넘었습니다. 같은 조건에서 다시 측정하고, 직장 체온을 확인하세요. 반복되거나 증상이 동반되면 수의사와 상담하세요.", "The change exceeds your chosen trend threshold. Repeat under the same conditions and check rectal temperature. Consult a vet if it persists or symptoms appear.", "Thay đổi vượt ngưỡng xu hướng đã đặt. Đo lại trong cùng điều kiện và kiểm tra nhiệt độ trực tràng. Liên hệ bác sĩ nếu lặp lại hoặc có triệu chứng."], "chipExtreme": ["높거나 낮은 피하 수치 · 재확인", "Unusual chip value · confirm", "Số đo dưới da khác thường · kiểm tra"], "chipExtremeBody": ["피하 수치가 크게 벗어났습니다. 직장 체온을 신속히 확인하고 수의사에게 연락하세요. 호흡곤란·쓰러짐·의식 변화가 있으면 재측정을 기다리지 말고 응급진료를 받으세요.", "The chip value is markedly unusual. Promptly check rectal temperature and contact a vet. Do not wait to remeasure if there is breathing difficulty, collapse or altered consciousness.", "Số đo vi mạch khác thường rõ rệt. Kiểm tra nhiệt độ trực tràng sớm và liên hệ bác sĩ. Không chờ đo lại nếu khó thở, ngã quỵ hoặc thay đổi ý thức."], "normal": ["직장 참고 범위 안", "Within rectal reference", "Trong khoảng tham chiếu trực tràng"], "normalBody": ["직장 체온 참고 범위 안입니다. 평소 컨디션·식욕·호흡도 함께 확인하세요. 증상이 있다면 정상 범위의 체온만으로 질병을 배제하지 않습니다.", "Within the rectal reference range. Also check appetite, breathing and behavior. A normal temperature does not rule out disease when symptoms are present.", "Trong khoảng tham chiếu trực tràng. Vẫn kiểm tra ăn uống, hô hấp và hành vi. Nhiệt độ bình thường không loại trừ bệnh nếu có triệu chứng."], "high": ["직장 참고 범위보다 높음", "Above rectal reference", "Cao hơn khoảng tham chiếu"], "highBody": ["더위·운동·흥분 또는 감염·염증 등 여러 원인이 가능합니다. 차분한 실내에서 재측정하고, 지속되거나 무기력·식욕저하가 있으면 수의사와 상담하세요.", "Heat, exercise, excitement, infection or inflammation are possible causes. Remeasure calmly indoors; consult a vet if it persists or lethargy or poor appetite occur.", "Có thể do nóng, vận động, kích thích, nhiễm trùng hoặc viêm. Đo lại khi bình tĩnh trong nhà; hỏi bác sĩ nếu kéo dài, lừ đừ hoặc bỏ ăn."], "low": ["직장 참고 범위보다 낮음", "Below rectal reference", "Thấp hơn khoảng tham chiếu"], "lowBody": ["추위·젖은 몸·마취 회복 또는 전신 상태 저하 등이 원인일 수 있습니다. 측정을 확인하고 따뜻하고 건조한 환경으로 옮기세요. 지속되거나 기력이 없으면 진료가 필요합니다.", "Cold, a wet coat, anesthetic recovery or systemic illness may contribute. Verify the reading and move to a warm, dry place. Persistent low readings or weakness need veterinary attention.", "Có thể do lạnh, lông ướt, hồi phục sau gây mê hoặc bệnh toàn thân. Kiểm tra số đo và đưa đến nơi ấm, khô. Nếu kéo dài hoặc yếu cần khám."], "urgentHigh": ["즉시 병원에 연락하세요", "Contact a veterinarian now", "Liên hệ bác sĩ thú y ngay"], "urgentHighBody": ["직장 체온이 40.5℃ 이상입니다. 더위 노출과 과도한 헐떡임이 있으면 시원한 곳으로 옮겨 몸보다 시원한 물로 적시고 바람을 쐬면서 병원에 연락·이동하세요. 다른 원인의 발열을 열사병으로 단정하지 마세요.", "Rectal temperature is at least 40.5°C. If heat exposure and excessive panting suggest heat illness, move to shade, wet the body with water cooler than the dog, provide airflow and contact and travel to a vet. Fever from another cause is not necessarily heatstroke.", "Nhiệt độ trực tràng từ 40,5°C. Nếu phơi nóng và thở hổn hển gợi ý bệnh do nhiệt, đưa đến nơi mát, làm ướt bằng nước mát hơn cơ thể, tạo luồng gió và liên hệ, đưa đến bác sĩ. Sốt do nguyên nhân khác không nhất thiết là sốc nhiệt."], "urgentLow": ["즉시 병원에 연락하세요", "Contact a veterinarian now", "Liên hệ bác sĩ thú y ngay"], "urgentLowBody": ["직장 체온이 37.0℃ 이하입니다. 마른 담요로 감싸고 따뜻한 환경에서 병원으로 이동하세요. 피부에 뜨거운 열원을 직접 대지 마세요.", "Rectal temperature is 37.0°C or lower. Wrap in a dry blanket and keep the environment warm during transport to a vet. Do not apply hot sources directly to the skin.", "Nhiệt độ trực tràng từ 37,0°C trở xuống. Quấn chăn khô, giữ môi trường ấm khi đưa đến bác sĩ. Không áp nguồn nóng trực tiếp lên da."], "symptoms": ["수치와 관계없이 응급진료", "Emergency care, regardless of temperature", "Cấp cứu bất kể nhiệt độ"], "symptomsBody": ["호흡곤란·쓰러짐·경련·의식 저하·비정상적인 잇몸색은 체온이 정상이어도 응급 징후입니다. 재측정이나 웹페이지 확인 때문에 이동을 늦추지 마세요.", "Breathing difficulty, collapse, seizures, reduced consciousness or abnormal gum color are emergency signs even at a normal temperature. Do not delay care to remeasure or use this page.", "Khó thở, ngã quỵ, co giật, giảm ý thức hoặc màu nướu bất thường là dấu hiệu cấp cứu dù nhiệt độ bình thường. Không trì hoãn để đo lại hoặc xem trang."], "redFlags": ["지금 보이는 응급 징후", "Current emergency signs", "Dấu hiệu cấp cứu hiện tại"], "breathing": ["호흡곤란·심한 헐떡임", "Breathing difficulty / severe panting", "Khó thở / thở hổn hển nặng"], "collapse": ["쓰러짐·경련·의식 변화", "Collapse / seizures / altered consciousness", "Ngã quỵ / co giật / thay đổi ý thức"], "gums": ["창백하거나 파란 잇몸", "Pale or blue gums", "Nướu nhợt hoặc xanh"], "count": ["최근 7일 측정", "Readings in 7 days", "Số lần đo trong 7 ngày"], "average": ["선택 방식 평균", "Average for selected method", "Trung bình theo cách đo"], "spread": ["선택 방식 변동폭", "Range for selected method", "Biên độ theo cách đo"], "sameMethod": ["같은 방식의 기록만 계산", "Same-method readings only", "Chỉ tính cùng cách đo"], "chartTitle": ["체온의 흐름", "Temperature over time", "Diễn biến nhiệt độ"], "chartSub": ["한 번의 수치보다, 이어지는 변화를 살펴보세요.", "Look beyond a single reading to the pattern over time.", "Theo dõi xu hướng thay vì chỉ một số đo."], "chartChip": ["피하 칩 기록", "Chip readings", "Số đo vi mạch"], "chartRectal": ["직장 체온 기록", "Rectal readings", "Số đo trực tràng"], "h24": ["24시간", "24h", "24 giờ"], "d7": ["7일", "7 days", "7 ngày"], "d30": ["30일", "30 days", "30 ngày"], "all": ["전체", "All", "Tất cả"], "measured": ["측정값", "Reading", "Số đo"], "referenceBand": ["참고 범위", "Reference band", "Vùng tham chiếu"], "personalBand": ["설정 기준 ±변화폭", "Baseline ± chosen threshold", "Cơ sở ± ngưỡng đã đặt"], "chartNote": ["측정 방식별로 분리해 표시합니다. 시간은 기기 수신·직접 입력 시각 기준입니다.", "Measurement methods are shown separately. Times use receipt or manual entry time.", "Hiển thị riêng từng cách đo. Thời gian dựa trên lúc nhận hoặc nhập thủ công."], "chartEmpty": ["이 방식의 기록이 아직 없습니다. 스캔하거나 직접 입력해 보세요.", "No records for this method yet. Scan or enter a reading.", "Chưa có bản ghi theo cách đo này. Hãy quét hoặc nhập số đo."], "trendTitle": ["기록 기반 변화 체크", "Record-based trend check", "Kiểm tra xu hướng từ lịch sử"], "needMore": ["같은 방식의 기록이 3개 이상 쌓이면 최근 변화 패턴을 확인합니다.", "Add at least 3 readings with the same method to check recent patterns.", "Cần ít nhất 3 số đo cùng cách đo để kiểm tra xu hướng gần đây."], "rising": ["최근 24시간 내 3회 연속 상승(총 0.5℃ 이상)했습니다. 같은 조건에서 확인하고 컨디션도 함께 살펴보세요.", "The last 3 readings rose consecutively within 24 hours, totaling at least 0.5°C. Check conditions and your dog's wellbeing.", "Ba lần đo gần nhất trong 24 giờ tăng liên tục, tổng ít nhất 0,5°C. Kiểm tra điều kiện và tình trạng của chó."], "falling": ["최근 24시간 내 3회 연속 하락(총 0.5℃ 이상)했습니다. 환경·측정 조건과 컨디션을 확인하세요.", "The last 3 readings fell consecutively within 24 hours, totaling at least 0.5°C. Check the environment, method and wellbeing.", "Ba lần đo gần nhất trong 24 giờ giảm liên tục, tổng ít nhất 0,5°C. Kiểm tra môi trường, cách đo và tình trạng."], "rapid": ["1시간 이내에 1.0℃ 이상 차이가 납니다. 측정 부위·활동·환경 차이를 확인하고 다시 측정하세요.", "Readings differ by at least 1.0°C within an hour. Check site, activity and environment and repeat.", "Chênh ít nhất 1,0°C trong một giờ. Kiểm tra vị trí, hoạt động, môi trường và đo lại."], "steady": ["현재 기록에서는 설정된 연속 상승·하락·급변 패턴이 감지되지 않았습니다. 질병을 배제하는 결과는 아닙니다.", "The configured rising, falling or rapid-change patterns were not detected. This does not rule out disease.", "Chưa phát hiện mô hình tăng, giảm liên tục hoặc thay đổi nhanh đã đặt. Điều này không loại trừ bệnh."], "patternNote": ["규칙 기반 참고 알림이며, 의학적으로 검증된 예측·진단 점수가 아닙니다.", "Rule-based prompts, not a clinically validated prediction or diagnostic score.", "Nhắc nhở theo quy tắc, không phải điểm dự đoán hay chẩn đoán đã kiểm chứng lâm sàng."], "recent": ["최근 기록", "Recent records", "Lịch sử gần đây"], "viewAll": ["전체 보기", "View all", "Xem tất cả"], "time": ["시각", "Time", "Thời gian"], "temperature": ["온도", "Temperature", "Nhiệt độ"], "method": ["측정 방식", "Method", "Cách đo"], "note": ["메모", "Note", "Ghi chú"], "backup": ["백업 저장", "Download backup", "Tải bản sao lưu"], "restore": ["백업 복원", "Restore backup", "Khôi phục bản sao"], "exportCSV": ["CSV 내보내기", "Export CSV", "Xuất CSV"], "noRecords": ["아직 저장된 기록이 없습니다.", "No saved records yet.", "Chưa có lịch sử đã lưu."], "quickGuide": ["안심 케어 노트", "Care notes", "Ghi chú chăm sóc"], "chipGuide": ["피하 칩과 직장 체온은 구분해요", "Keep chip and rectal readings separate", "Phân biệt số đo vi mạch và trực tràng"], "chipGuideBody": ["측정 부위·환경·개체에 따라 차이가 나므로 일률적으로 보정값을 더하지 않습니다. 반복되는 변화는 직장 체온과 임상 증상으로 확인하세요.", "Differences depend on site, environment and individual; no universal offset is added. Verify repeated changes with rectal temperature and clinical signs.", "Chênh lệch tùy vị trí, môi trường và cá thể; không cộng hệ số hiệu chỉnh chung. Xác minh thay đổi lặp lại bằng nhiệt độ trực tràng và triệu chứng."], "noDrugs": ["사람용 해열제를 주지 마세요", "Do not give human fever medicines", "Không cho dùng thuốc hạ sốt của người"], "noDrugsBody": ["아세트아미노펜·이부프로펜 등을 임의로 투약하지 마세요. 원인 확인과 약물 선택은 수의사의 판단이 필요합니다.", "Do not give acetaminophen, ibuprofen or other human drugs without veterinary direction. A vet must assess the cause and appropriate treatment.", "Không tự cho dùng paracetamol, ibuprofen hoặc thuốc người khác. Bác sĩ cần đánh giá nguyên nhân và điều trị phù hợp."], "clinicalNote": ["이 화면은 기록·관찰을 돕습니다. 체온만으로 감염·열사병 등 원인을 진단하지 않습니다.", "This screen supports recording and observation. Temperature alone cannot diagnose infection, heatstroke or another cause.", "Trang hỗ trợ ghi chép và quan sát. Nhiệt độ đơn thuần không chẩn đoán được nhiễm trùng, sốc nhiệt hay nguyên nhân khác."], "triageNote": ["직장 체온 40.5℃ 이상 또는 37.0℃ 이하는 이 화면의 보수적인 병원 연락 기준입니다. 응급 증상은 수치보다 우선합니다.", "Rectal values ≥40.5°C or ≤37.0°C trigger this screen's conservative vet-contact advice. Emergency symptoms take priority over numbers.", "Số đo trực tràng ≥40,5°C hoặc ≤37,0°C kích hoạt lời khuyên liên hệ bác sĩ theo ngưỡng thận trọng của trang. Triệu chứng cấp cứu được ưu tiên hơn số đo."], "healthBaseline": ["건강한 날의 기준을 사용해요", "Use a healthy-day baseline", "Dùng mức cơ sở khi khỏe"], "healthBaselineBody": ["개인 기준은 보호자·수의사가 건강한 안정 상태의 반복 측정으로 정하세요. 기본 변화 알림 0.5℃는 관찰용 설정값이며 질병 판정 기준이 아닙니다.", "Set an individual baseline with your vet using repeated healthy, resting measurements. The default 0.5°C trend threshold is an observation setting, not a disease cutoff.", "Cùng bác sĩ đặt mức cơ sở từ các phép đo lặp lại khi khỏe và nghỉ ngơi. Ngưỡng thay đổi mặc định 0,5°C chỉ để quan sát, không phải ngưỡng bệnh."], "firstAid": ["더위가 의심될 때", "When overheating is suspected", "Khi nghi quá nóng"], "firstAidBody": ["시원한 곳으로 옮기고, 몸보다 시원한 물로 적신 뒤 선풍기·에어컨 바람을 쐬며 병원에 연락하세요. 젖은 수건으로 몸을 감싸두거나 억지로 물을 먹이지 마세요.", "Move to a cool place, wet the body with water cooler than the dog and provide fan or air-conditioning airflow while contacting a vet. Do not wrap the body in wet towels or force water into the mouth.", "Đưa đến nơi mát, làm ướt bằng nước mát hơn cơ thể và tạo luồng gió trong khi liên hệ bác sĩ. Không quấn kín bằng khăn ướt hoặc ép uống nước."], "lowAid": ["몸이 차갑고 기력이 없을 때", "When cold and weak", "Khi lạnh và yếu"], "lowAidBody": ["젖었다면 부드럽게 말리고 마른 담요로 감싸 따뜻한 실내에서 병원으로 이동하세요. 핫팩·전기장판 등 뜨거운 열원을 피부에 직접 대지 마세요.", "If wet, dry gently and wrap in a dry blanket. Keep warm during transport to a vet. Avoid direct contact with hot packs or heating pads.", "Nếu ướt, lau khô nhẹ nhàng và quấn chăn khô. Giữ ấm khi đưa đến bác sĩ. Không áp túi nóng hay đệm sưởi trực tiếp lên da."], "sourceTitle": ["안내 근거와 범위", "Sources and scope", "Nguồn và phạm vi"], "name": ["강아지 이름", "Dog's name", "Tên chó"], "chipId": ["칩 번호 (선택)", "Chip ID (optional)", "Mã vi mạch (không bắt buộc)"], "baselineHint": ["건강하고 안정된 날의 피하 측정값. 모르면 비워 두세요.", "Use a healthy, resting chip measurement. Leave blank if unknown.", "Dùng số đo vi mạch khi khỏe và nghỉ ngơi. Để trống nếu chưa biết."], "threshold": ["변화 알림 폭 (℃)", "Trend threshold (°C)", "Ngưỡng thay đổi (°C)"], "save": ["저장", "Save", "Lưu"], "cancel": ["취소", "Cancel", "Hủy"], "addReading": ["직장 체온 입력", "Enter rectal temperature", "Nhập nhiệt độ trực tràng"], "saveReading": ["측정값 저장", "Save reading", "Lưu số đo"], "context": ["측정 상황", "Context", "Hoàn cảnh"], "rest": ["안정 상태", "Resting", "Nghỉ ngơi"], "activity": ["운동·흥분 후", "After exercise / excitement", "Sau vận động / kích thích"], "other": ["기타·확인 필요", "Other / needs confirmation", "Khác / cần xác minh"], "manualChip": ["피하 온도 직접 입력", "Chip value · manual entry", "Nhiệt độ dưới da · nhập tay"], "receiptTime": ["기록 시각", "Record time", "Thời gian ghi"], "saved": ["저장했습니다.", "Saved.", "Đã lưu."], "storageError": ["저장 공간에 기록하지 못했습니다. 저장됨으로 표시하지 않습니다. 백업 후 브라우저 공간을 확인해 주세요.", "Could not write to browser storage; the change was not saved. Back up and check available browser space.", "Không ghi được vào bộ nhớ trình duyệt; thay đổi chưa được lưu. Sao lưu và kiểm tra dung lượng."], "addFirst": ["먼저 반려견을 등록해 주세요.", "Please add your dog first.", "Vui lòng thêm chó trước."], "unsupported": ["갤럭시 Chrome에서 연결해 주세요. 이 브라우저는 Web Bluetooth를 지원하지 않습니다.", "Use Chrome on Samsung Galaxy. This browser does not support Web Bluetooth.", "Dùng Chrome trên Samsung Galaxy. Trình duyệt này không hỗ trợ Web Bluetooth."], "selectDevice": ["기기를 선택해 주세요.", "Select your device.", "Chọn thiết bị."], "connectError": ["연결에 실패했습니다. 다른 앱의 연결을 해제하고 다시 시도해 주세요.", "Connection failed. Disconnect other apps and try again.", "Kết nối thất bại. Ngắt các ứng dụng khác và thử lại."], "cancelled": ["기기 선택을 취소했습니다.", "Device selection cancelled.", "Đã hủy chọn thiết bị."], "reconnect": ["연결이 해제되었습니다. 다시 연결할 수 있습니다.", "Disconnected. You can reconnect.", "Đã ngắt kết nối. Có thể kết nối lại."], "connectionGuide": ["연결 전 확인", "Before connecting", "Trước khi kết nối"], "step1": ["갤럭시 Chrome에서 이 HTTPS 페이지를 열고 스캐너 전원을 켜세요.", "Open this HTTPS page in Chrome on Samsung Galaxy and turn on the scanner.", "Mở trang HTTPS bằng Chrome trên Samsung Galaxy và bật máy quét."], "step2": ["와이펫 앱·nRF Connect의 연결을 해제한 뒤 연결 버튼에서 SC400을 선택하세요.", "Disconnect the YPET app and nRF Connect, then select SC400 using Connect scanner.", "Ngắt ứng dụng YPET và nRF Connect, sau đó chọn SC400 bằng nút kết nối."], "step3": ["반려견을 선택하고 삽입 부위를 스캔하세요. 같은 칩의 새 측정은 자동 저장됩니다.", "Choose your dog and scan the implant site. New readings from a matching chip are saved automatically.", "Chọn chó và quét vùng cấy. Số đo mới từ vi mạch trùng khớp được tự lưu."], "packetNote": ["두 개의 제공 샘플로 칩 번호·온도 해석을 확인했습니다. 제조사 체크섬 규격과 실기기 재검증은 아직 필요합니다. 알 수 없는 패킷은 체온으로 추측하지 않습니다.", "Chip ID and temperature decoding match the two supplied samples. Manufacturer checksum details and further physical-device verification remain necessary. Unknown packets are not guessed as temperatures.", "Giải mã mã vi mạch và nhiệt độ khớp hai mẫu đã cung cấp. Vẫn cần thông tin checksum từ nhà sản xuất và kiểm chứng thêm trên thiết bị. Không đoán nhiệt độ từ gói chưa biết."], "diagnostics": ["수신 진단", "Reception diagnostics", "Chẩn đoán nhận dữ liệu"], "exportRaw": ["원시 로그 저장", "Export raw log", "Xuất nhật ký thô"], "noRaw": ["아직 수신 데이터가 없습니다.", "No data received yet.", "Chưa nhận dữ liệu."], "pendingTitle": ["새 측정이 도착했어요", "A new reading arrived", "Đã có số đo mới"], "bind": ["선택한 반려견과 연결·저장", "Link to selected dog and save", "Liên kết với chó đã chọn và lưu"], "mismatch": ["선택한 반려견과 칩 번호가 다릅니다. 올바른 프로필을 선택하거나 새로 등록해 주세요.", "The chip differs from the selected dog. Select the correct profile or add a new one.", "Vi mạch khác chó đã chọn. Chọn hồ sơ đúng hoặc thêm hồ sơ mới."], "newChip": ["이 칩을 선택한 반려견과 연결해 저장할까요?", "Link this chip to the selected dog and save?", "Liên kết vi mạch này với chó đã chọn và lưu?"], "invalidReading": ["숫자와 측정 범위를 확인해 주세요.", "Check the number and measurement range.", "Kiểm tra số và dải đo."], "noDevice": ["수신 알림 항목을 찾지 못했습니다.", "No notification characteristic found.", "Không tìm thấy đặc tính thông báo."], "limit": ["기록이 5,000개에 도달했습니다. 백업 후 보관 방식을 정리해 주세요.", "The 5,000-record limit has been reached. Back up and review your storage.", "Đã đạt giới hạn 5.000 bản ghi. Hãy sao lưu và kiểm tra lưu trữ."], "restoreConfirm": ["백업 파일로 현재 반려견·기록을 교체할까요? 기존 자료를 먼저 백업해 주세요.", "Replace current dogs and records with this backup? Back up existing data first.", "Thay chó và lịch sử hiện tại bằng bản sao lưu này? Hãy sao lưu dữ liệu cũ trước."], "invalidBackup": ["올바른 백업 파일이 아닙니다. 데이터는 변경하지 않았습니다.", "Invalid backup file. Your data was not changed.", "Tệp sao lưu không hợp lệ. Dữ liệu không bị thay đổi."], "confirmChip": ["저장할 반려견과 칩 번호를 확인해 주세요.", "Confirm the dog and chip ID before saving.", "Xác nhận chó và mã vi mạch trước khi lưu."], "keepLocal": ["고객·반려견 기록을 서버로 보내지 않습니다.", "Dog records are not sent to a server.", "Không gửi dữ liệu chó lên máy chủ."], "healthTerms": ["정상 참고 범위는 성견의 직장 측정 기준입니다. 어린 강아지·마취 중·기저질환 개체는 수의사의 개별 기준이 필요합니다.", "The reference is for adult dogs measured rectally. Puppies, anesthetized dogs and dogs with underlying disease need individual veterinary guidance.", "Khoảng tham chiếu dành cho chó trưởng thành đo trực tràng. Chó con, đang gây mê hoặc có bệnh nền cần hướng dẫn riêng của bác sĩ."], "bodyTemp": ["체온", "Temperature", "Nhiệt độ"], "home": ["홈페이지", "Website", "Trang chủ"], "edit": ["수정", "Edit", "Sửa"], "remove": ["삭제", "Delete", "Xóa"], "removeReading": ["이 측정 기록을 삭제할까요?", "Delete this reading?", "Xóa bản ghi này?"], "noSymptoms": ["선택하지 않은 증상이 없다는 뜻은 아닙니다.", "Unchecked symptoms are not confirmation that they are absent.", "Không chọn không có nghĩa là chắc chắn không có triệu chứng."], "recordsSub": ["선택한 반려견의 실제 저장 기록입니다.", "Saved records for the selected dog.", "Lịch sử đã lưu của chó đang chọn."], "demoNoBle": ["데모를 종료한 뒤 실제 스캐너를 연결해 주세요.", "Exit demo before connecting a real scanner.", "Thoát chế độ xem thử trước khi kết nối máy quét thật."], "rawReceived": ["패킷 수신 · 지원 형식인지 확인 중", "Packet received · checking supported format", "Đã nhận gói · đang kiểm tra định dạng"], "baselineDelta": ["기준 대비", "Versus baseline", "So với cơ sở"], "emptyIntro": ["반려견 이름 하나로 시작하세요.", "Start with your dog's name.", "Bắt đầu bằng tên chó."], "emptyBody": ["스캐너 측정과 직접 입력을 모아, 반려견만의 체온 흐름을 기록합니다.", "Bring scanner and manual readings together to track your dog's temperature over time.", "Kết hợp số đo máy quét và nhập tay để theo dõi nhiệt độ của chó theo thời gian."]};
'use strict';
const KEY='ypet-vitals-v1',MAX=5000,root=document.getElementById('dashboard'),$=id=>document.getElementById(id);
let lang=['en','vi'].includes(document.documentElement.lang)?document.documentElement.lang:'ko';
const t=k=>COPY[k]?.[['ko','en','vi'].indexOf(lang)]||k;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const clone=v=>JSON.parse(JSON.stringify(v));
let loadError=false,state={format:'ypet-vitals-v1',pets:[],records:[]};
try{const raw=localStorage.getItem(KEY);if(raw){const value=JSON.parse(raw);if(!VitalsModel.validateBackup(value))throw Error('invalid');state=value;}}catch(error){loadError=true;}
let selected=state.pets[0]?.id||'',page='dashboard',method='chip',period='7',demo=false,demoDB=null,symptoms={breathing:false,collapse:false,gums:false};
let device=null,connected=false,connecting=false,subscriptions=[],pending=null,rawLog=[],lastPacket={hex:'',time:0},stream=new SC400Codec.Stream(),toastTimer;
function db(){return demo?demoDB:state;}function pet(){return db().pets.find(p=>p.id===selected)||null;}
function readings(){return db().records.filter(r=>r.petId===selected).sort((a,b)=>Date.parse(a.time)-Date.parse(b.time));}
function rowsForMethod(){return readings().filter(r=>r.method===method&&(r.method!=='chip'||r.temp>=30&&r.temp<=45));}
function latest(){return readings().at(-1)||null;}
function fmtTime(value,full=false){try{return new Intl.DateTimeFormat(lang==='ko'?'ko-KR':lang==='vi'?'vi-VN':'en-GB',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',...(full?{year:'numeric'}:{})}).format(new Date(value));}catch(error){return '—';}}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),6000);}
function persist(next){if(demo){demoDB=next;return true;}if(loadError){toast(t('storageError'));return false;}try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true;}catch(error){toast(t('storageError'));return false;}}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function icon(key){return {dashboard:'◈',records:'▤',guide:'♡',scanner:'⌁'}[key]||'·';}
function button(action,label,classes='',extra=''){return `<button type="button" class="button ${classes}" data-action="${action}" ${extra}>${t(label)}</button>`;}
function severity(code){return ['urgentHigh','urgentLow','symptoms'].includes(code)?'critical':['chipExtreme','chipShift','high','low','sensor'].includes(code)?'warning':'';}
function assessment(record=latest()){return VitalsModel.assess(record,pet(),Object.values(symptoms).some(Boolean));}
function statusBody(code){return t(code+'Body');}
function profileToolbar(){const p=pet();return `<div class="toolbar"><div class="pet-select"><span class="avatar" aria-hidden="true">♧</span><div><label for="pet-choice">${t('pet')}</label><select id="pet-choice"><option value="" ${p?'hidden':''}>${t('selectPet')}</option>${db().pets.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div>${button('addPet','addPet')}${p?button('editPet','editPet','quiet'):''}<span class="spacer"></span><span class="connection ${connected?'online':''}"><i class="dot"></i>${t(connected?'connected':'offline')}</span>${button(connected?'disconnect':'connect',connected?'disconnect':'connect','primary',connecting?'disabled':'')}${button('manual','manual','',p?'':'disabled')}</div>`;}
function hero(){const p=pet(),record=pending||latest(),code=assessment(record),isPending=!!pending;const delta=record?.method==='chip'&&p?.baseline!=null?(record.temp-p.baseline):null;return `<section class="panel hero"><div class="hero-head"><div><span class="eyebrow">TEMPERATURE MONITOR</span><div style="margin-top:7px"><small>${record?esc(p?.name||'SC400'):t('noReading')} · ${t(isPending?'fresh':'latest')}</small></div></div><span class="badge ${severity(code)?'alert':''}">${record?t(record.method==='chip'?'chip':'rectal'):t('none')}</span></div><div class="reading"><strong>${record?Number(record.temp).toFixed(1):'—'}</strong><span>°C</span></div><small>${record?fmtTime(record.time,true)+' · '+t(record.source==='ble'?'ble':'manual'):t('emptyIntro')}</small><div class="hero-foot"><div><small>${t('reference')}</small><b>37.5–39.2°C</b></div><div><small>${t('baselineDelta')}</small><b>${delta==null?'—':(delta>=0?'+':'')+delta.toFixed(1)+'°C'}</b></div></div><div class="hero-note">${record?.method==='rectal'?t('healthTerms'):t('methodNote')}</div></section>`;}
function statusCard(){const record=pending||latest(),code=assessment(record);return `<section class="panel"><span class="tag">CARE CHECK</span><h2 style="margin-top:8px">${t('healthCheck')}</h2><div class="status-title">${t(code)}</div><div class="status-copy">${statusBody(code)}</div><div class="small-actions">${button('manual','addReading','',pet()?'':'disabled')}${button('guide','guide','quiet')}</div><details class="symptoms" ${Object.values(symptoms).some(Boolean)?'open':''}><summary class="mini">${t('redFlags')} +</summary>${['breathing','collapse','gums'].map(k=>`<label><input type="checkbox" data-symptom="${k}" ${symptoms[k]?'checked':''}>${t(k)}</label>`).join('')}<div class="mini">${t('noSymptoms')}</div></details></section>`;}
function metrics(){const all=rowsForMethod(),week=readings().filter(r=>Date.parse(r.time)>=Date.now()-7*86400000).length;const avg=all.length?all.reduce((s,r)=>s+r.temp,0)/all.length:null;const spread=all.length?Math.max(...all.map(r=>r.temp))-Math.min(...all.map(r=>r.temp)):null;return `<div class="metrics"><div class="metric"><span>${t('count')}</span><b>${week}</b><small>${t('records')}</small></div><div class="metric"><span>${t('average')}</span><b>${avg==null?'—':avg.toFixed(1)+'°'}</b><small>${t('sameMethod')}</small></div><div class="metric"><span>${t('spread')}</span><b>${spread==null?'—':spread.toFixed(1)+'°'}</b><small>${t('sameMethod')}</small></div></div>`;}
function graph(){let all=rowsForMethod();if(period!=='all')all=all.filter(r=>Date.parse(r.time)>=Date.now()-Number(period)*86400000);const clipped=all.length>120;all=all.slice(-120);if(!all.length)return `<div class="chart-empty">${t('chartEmpty')}</div>`;
 const p=pet(),width=760,height=245,pad={l:43,r:17,t:18,b:29};let low=Math.min(...all.map(r=>r.temp))-.45,high=Math.max(...all.map(r=>r.temp))+.45;let band=null;
 if(method==='rectal'){low=Math.min(low,37);high=Math.max(high,39.6);band=[37.5,39.2];}else if(p?.baseline!=null){band=[p.baseline-(p.threshold||.5),p.baseline+(p.threshold||.5)];low=Math.min(low,band[0]-.2);high=Math.max(high,band[1]+.2);}
 low=Math.floor(low*2)/2;high=Math.ceil(high*2)/2;if(high-low<1)high=low+1;
 const minTime=Date.parse(all[0].time),maxTime=Date.parse(all.at(-1).time),x=r=>all.length===1?width/2:pad.l+(Date.parse(r.time)-minTime)/(maxTime-minTime||1)*(width-pad.l-pad.r),y=v=>pad.t+(high-v)/(high-low)*(height-pad.t-pad.b);
 const line=all.map((r,i)=>`${i?'L':'M'}${x(r).toFixed(1)},${y(r.temp).toFixed(1)}`).join(' ');const area=line+` L${x(all.at(-1)).toFixed(1)},${height-pad.b} L${x(all[0]).toFixed(1)},${height-pad.b} Z`;
 const ticks=Array.from({length:5},(_,i)=>low+(high-low)*i/4);const labels=[0,Math.floor((all.length-1)/2),all.length-1].filter((v,i,a)=>a.indexOf(v)===i);
 return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(t('chartTitle')+' '+all.length+' '+t('records'))}"><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#28b6a3" stop-opacity=".18"/><stop offset="1" stop-color="#28b6a3" stop-opacity="0"/></linearGradient></defs>${band?`<rect x="${pad.l}" y="${y(band[1])}" width="${width-pad.l-pad.r}" height="${y(band[0])-y(band[1])}" fill="#e6f5ed"/>`:''}${ticks.map(v=>`<line x1="${pad.l}" y1="${y(v)}" x2="${width-pad.r}" y2="${y(v)}" stroke="#e9f0f1" stroke-dasharray="3 5"/><text x="${pad.l-9}" y="${y(v)+3}" text-anchor="end">${v.toFixed(1)}°</text>`).join('')}<path d="${area}" fill="url(#chart-fill)"/><path d="${line}" fill="none" stroke="#18a693" stroke-width="2.5" stroke-linejoin="round"/>${all.map((r,i)=>`<circle cx="${x(r)}" cy="${y(r.temp)}" r="${i===all.length-1?5:3.5}" fill="${method==='rectal'&&(r.temp>39.2||r.temp<37.5)?'#d68b58':'#21ad9c'}" stroke="white" stroke-width="2" tabindex="0"><title>${esc(fmtTime(r.time,true)+' · '+r.temp.toFixed(1)+'°C')}</title></circle>`).join('')}${labels.map(i=>`<text x="${x(all[i])}" y="${height-6}" text-anchor="middle">${esc(fmtTime(all[i].time))}</text>`).join('')}</svg>${clipped?'<div class="mini">'+(lang==='ko'?'최근 120개 표시':lang==='en'?'Showing the latest 120 readings':'Hiển thị 120 số đo gần nhất')+'</div>':''}`;
}
function chartPanel(){return `<section class="panel chart-panel"><div class="section-head"><div><h2>${t('chartTitle')}</h2><p>${t('chartSub')}</p></div><span class="pill">°C</span></div><div class="chart-controls"><select id="method-choice" aria-label="${t('method')}"><option value="chip" ${method==='chip'?'selected':''}>${t('chartChip')}</option><option value="rectal" ${method==='rectal'?'selected':''}>${t('chartRectal')}</option></select><div class="segmented">${[['1','h24'],['7','d7'],['30','d30'],['all','all']].map(([v,k])=>`<button data-period="${v}" class="${period===v?'active':''}">${t(k)}</button>`).join('')}</div></div><div class="legend"><span><i></i>${t('measured')}</span>${method==='rectal'||pet()?.baseline!=null?`<span><i class="band"></i>${t(method==='rectal'?'referenceBand':'personalBand')}</span>`:''}</div>${graph()}<div class="chart-foot">${t('chartNote')}</div><div class="insight"><b>${t('trendTitle')}</b><br>${t(VitalsModel.trend(rowsForMethod()))}<div class="mini" style="margin-top:6px">${t('patternNote')}</div></div></section>`;}
function rangePanel(){const p=pet();return `<section class="panel"><span class="tag">REFERENCE & BASELINE</span><h2 style="margin-top:9px">${t('reference')}</h2><div style="font-size:32px;letter-spacing:-1px;margin-top:15px">37.5–39.2<span style="font-size:17px;color:#92a4a8"> °C</span></div><div class="range-bar"></div><div class="range-labels"><span>&lt;37.5</span><span>37.5–39.2</span><span>&gt;39.2</span></div><div class="reference-box">${t('methodNote')}</div><div class="info-row"><span>${t('baseline')}</span><b>${p?.baseline!=null?p.baseline.toFixed(1)+'°C':t('notSet')}</b></div><div class="info-row"><span>${t('threshold')}</span><b>±${Number(p?.threshold||.5).toFixed(1)}°C</b></div><p>${t('baselineHint')}</p>${button('editPet','editPet','quiet',p?'':'disabled')}<p style="font-size:10px">${t('triageNote')}</p></section>`;}
function recordTable(limit=10){const list=readings().slice().reverse().slice(0,limit);if(!list.length)return `<div class="empty">${t('noRecords')}</div>`;return `<div class="table-wrap"><table class="table"><thead><tr><th>${t('time')}</th><th>${t('temperature')}</th><th>${t('method')}</th><th>${t('note')}</th>${limit>10?'<th></th>':''}</tr></thead><tbody>${list.map(r=>`<tr><td>${fmtTime(r.time)}<br><small>${t(r.source==='ble'?'ble':'manual')}</small></td><td class="temp">${r.temp.toFixed(1)}°C</td><td><span class="pill">${t(r.method==='chip'?'chip':'rectal')}</span></td><td title="${esc(r.note||'')}">${esc((r.note||'—').slice(0,40))}</td>${limit>10?`<td><button class="card-link" data-delete="${esc(r.id)}">${t('remove')}</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function notes(){return `<section class="panel"><h2>${t('quickGuide')}</h2><div class="guide-card"><h3>${t('chipGuide')}</h3><p>${t('chipGuideBody')}</p></div><div class="guide-card"><h3>${t('noDrugs')}</h3><p>${t('noDrugsBody')}</p></div><div class="small-actions">${button('guide','guide','quiet')}</div></section>`;}
function sourceLinks(){return `<div class="sources"><b>${t('sourceTitle')}</b><br><a href="https://www.merckvetmanual.com/reference-values-and-conversion-tables/reference-guides/normal-rectal-temperature-ranges">Merck Veterinary Manual · Reference</a><a href="https://www.rvc.ac.uk/small-animal-vet/teaching-and-research/fact-files/heatstroke-in-dogs-and-cats">RVC · Heatstroke</a><a href="https://www.rvc.ac.uk/small-animal-vet/general-practice/pet-care-advice/first-aid-guide">RVC · First aid</a><p>${t('healthTerms')}</p></div>`;}
function pendingPanel(){if(!pending)return '';return `<section class="pending"><b>${t('pendingTitle')} · ${pending.temp.toFixed(1)}°C</b><br>RFID ${esc(pending.chip)} · ${fmtTime(pending.time)}<br>${pending.temp<30||pending.temp>45?t('sensorBody'):pet()?.chip&&pet().chip!==pending.chip?t('mismatch'):t('confirmChip')}<br>${button('bind','bind','primary',!pet()||pending.temp<30||pending.temp>45?'disabled':'')}${button('addPet','addPet')}${button('dismiss','cancel','quiet')}</section>`;}
function guidePage(){return `<div class="guide-grid">${[['reference','healthTerms'],['chipGuide','chipGuideBody'],['healthBaseline','healthBaselineBody'],['high','highBody'],['low','lowBody'],['firstAid','firstAidBody'],['lowAid','lowAidBody'],['noDrugs','noDrugsBody']].map(([h,b])=>`<article class="guide-card"><h3>${t(h)}</h3><p>${t(b)}</p></article>`).join('')}</div><div class="emergency-banner">${t('symptomsBody')}</div><div class="reference-box">${t('triageNote')}</div>${sourceLinks()}`;}
function devicePage(){return `<div class="grid"><section class="panel"><h2>SC400 · Bluetooth LE</h2><p>${t('connectionGuide')}</p>${[1,2,3].map(i=>`<div class="step"><b>${i}</b><div>${t('step'+i)}</div></div>`).join('')}<div class="small-actions">${button(connected?'disconnect':'connect',connected?'disconnect':'connect','primary')}${button('raw','exportRaw','',rawLog.length?'':'disabled')}</div><p>${t('packetNote')}</p><details><summary class="mini">GATT</summary><pre class="raw-log">3a95e1b9-d1a2-4876-8335-02108039b3a2\nNOTIFY: 3a95e1b8-d1a2-4876-8335-02108039b3a2</pre></details></section><section class="panel"><h2>${t('diagnostics')}</h2><p>${t('chartNote')}</p><pre class="raw-log">${rawLog.length?esc(rawLog.slice(-8).map(r=>r.time+'\n'+r.hex).join('\n\n')):t('noRaw')}</pre><p>${t('packetNote')}</p></section></div>`;}
function browserHelp(){
 const ua=navigator.userAgent,android=/Android/i.test(ua),ios=/iPhone|iPad|iPod/i.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),inApp=/KAKAOTALK|Instagram|FBAN|FBAV|Line\//i.test(ua);
 const language=['ko','en','vi'].indexOf(lang),msg=(ko,en,vi)=>[ko,en,vi][language];
 const url=new URL('scanner.html',location.href);url.searchParams.set('v','20261027-browser1');if(lang!=='ko')url.searchParams.set('lang',lang);
 const intent='intent://'+url.host+url.pathname+url.search+'#Intent;scheme='+url.protocol.slice(0,-1)+';package=com.android.chrome;S.browser_fallback_url='+encodeURIComponent(url.href)+';end';
 const title=ios?msg('아이폰 스캐너 연결 안내','Scanner connection on iPhone','Kết nối máy quét trên iPhone'):inApp?msg('카톡·앱 안에서 열었나요? Chrome으로 연결하세요','Opened inside an app? Connect with Chrome','Đang mở trong ứng dụng? Hãy kết nối bằng Chrome'):msg('카톡으로 받았다면? 브라우저 연결 안내','Received a link in chat? Browser connection help','Nhận liên kết qua tin nhắn? Hướng dẫn trình duyệt');
 const note=ios?msg('아이폰의 일반 Safari·Chrome에서는 이 사이트의 블루투스 직접 연결을 지원하지 않습니다. Chrome으로 옮겨도 해결되지 않습니다. 기록 보기와 직접 입력은 이용할 수 있습니다.','Standard Safari and Chrome on iPhone do not support this site’s direct Bluetooth connection. Switching to Chrome will not enable it. Viewing records and manual entry remain available.','Safari và Chrome thông thường trên iPhone không hỗ trợ kết nối Bluetooth trực tiếp của trang này. Chuyển sang Chrome không khắc phục được. Bạn vẫn có thể xem lịch sử và nhập tay.'):msg('카카오톡 등 앱 안에서는 스캐너 연결이 제한될 수 있습니다. 안드로이드에서는 아래 버튼으로 Chrome 열기를 시도하세요.','In-app browsers such as KakaoTalk may prevent scanner connection. On Android, use the button below to try opening Chrome.','Trình duyệt trong ứng dụng như KakaoTalk có thể chặn kết nối máy quét. Trên Android, nhấn nút bên dưới để thử mở Chrome.');
 const manual=msg('버튼이 작동하지 않으면 카톡 상단 메뉴(⋮ 또는 ···) → 다른 브라우저로 열기 → Chrome을 선택하세요. 메뉴 이름은 기기마다 다를 수 있습니다. Chrome이 없다면 설치한 뒤 링크를 붙여 넣으세요.','If the button does not work: open the chat browser menu (⋮ or ···), choose Open in another browser, then Chrome. Menu names vary. If Chrome is not installed, install it and paste the link.','Nếu nút không hoạt động: mở menu (⋮ hoặc ···), chọn mở bằng trình duyệt khác rồi chọn Chrome. Tên menu có thể khác. Nếu chưa có Chrome, hãy cài đặt rồi dán liên kết.');
 return `<details class="browser-help" ${inApp||(ios&&!navigator.bluetooth)||(android&&!navigator.bluetooth)?'open':''}><summary>${title}</summary><div class="browser-help-body"><p>${note}</p><div class="browser-help-actions">${android&&!ios?`<a class="browser-chrome" href="${esc(intent)}">${msg('Chrome으로 열기','Open in Chrome','Mở bằng Chrome')} ↗</a>`:''}<button type="button" data-browser-copy>${msg('링크 복사','Copy link','Sao chép liên kết')}</button></div>${!ios?`<p>${manual}</p>`:''}<p class="browser-storage">${msg('브라우저가 바뀌면 저장 기록은 자동으로 옮겨지지 않습니다. 기존 기록은 측정 기록 메뉴에서 백업한 뒤 새 브라우저에서 복원하세요.','Saved records do not move automatically between browsers. Back them up in Records, then restore in the new browser.','Lịch sử không tự chuyển giữa các trình duyệt. Sao lưu trong Lịch sử đo rồi khôi phục ở trình duyệt mới.')}</p><label class="browser-copy-fallback" hidden>${msg('주소를 길게 눌러 복사하세요','Press and hold the address to copy','Nhấn giữ địa chỉ để sao chép')}<input readonly aria-label="Scanner page URL" value="${esc(url.href)}"></label><span class="browser-copy-status" role="status" aria-live="polite"></span></div></details>`;
}
document.addEventListener('click',async event=>{if(!event.target.closest('[data-browser-copy]'))return;const panel=event.target.closest('.browser-help'),field=panel.querySelector('input'),status=panel.querySelector('.browser-copy-status');try{await navigator.clipboard.writeText(field.value);status.textContent=lang==='ko'?'링크를 복사했어요. Chrome 주소창에 붙여 넣으세요.':lang==='vi'?'Đã sao chép. Dán vào thanh địa chỉ Chrome.':'Link copied. Paste it into Chrome’s address bar.';}catch(error){field.parentElement.hidden=false;field.focus();field.select();}});
function render(){lang=['en','vi'].includes(document.documentElement.lang)?document.documentElement.lang:'ko';const p=pet();if(!p&&selected)selected=db().pets[0]?.id||'';const code=assessment(pending||latest());root.innerHTML=`<aside class="sidebar"><a class="brand" href="index.html?v=20261027-vitals1${lang!=='ko'?'&lang='+lang:''}"><img src="assets/4fa57eabcee81.png" alt="YPET SAFE"><small>CONNECTED CARE</small></a><div class="side-label">WORKSPACE</div><nav class="side-nav" aria-label="${t('dashboard')}">${['dashboard','records','guide','scanner'].map(k=>`<button data-action="${k}" class="${page===k?'active':''}"><span class="side-icon">${icon(k)}</span><span class="label">${t(k)}</span></button>`).join('')}</nav><div class="side-bottom"><b>LOCAL-FIRST PRIVACY</b>${t('local')}<br>${t('keepLocal')}</div></aside><main class="workspace"><header class="topline"><div><span class="eyebrow">YPET SAFE / WELLNESS STUDIO</span><h1>Temperature studio<span style="color:#17a291">.</span></h1></div><span class="date-label">${new Intl.DateTimeFormat(lang==='ko'?'ko-KR':lang==='vi'?'vi-VN':'en-GB',{month:'short',day:'numeric',weekday:'short'}).format(new Date())}</span></header><p class="intro">${t('subtitle')}</p>${browserHelp()}${profileToolbar()}${demo?`<div class="demo-banner"><span>${t('demoNote')}</span><button data-action="demoExit">${t('demoExit')} ↗</button></div>`:''}${loadError?`<div class="emergency-banner">${t('storageError')}</div>`:''}${!demo?`<div style="text-align:right;margin:-7px 0 13px"><button class="card-link" data-action="demo">${t('demo')} ↗</button></div>`:''}${Object.values(symptoms).some(Boolean)?`<div class="emergency-banner">${t('symptomsBody')}</div>`:''}${pendingPanel()}${page==='dashboard'?`${!p?`<div class="panel empty" style="margin-bottom:18px"><div style="font-size:31px;color:#27a48e">♧</div><b>${t('emptyIntro')}</b>${t('emptyBody')}<div class="small-actions" style="justify-content:center">${button('addPet','addPet','primary')}${button('demo','demo')}</div></div>`:''}<div class="grid">${hero()}${statusCard()}</div>${metrics()}<div class="grid">${chartPanel()}${rangePanel()}</div><div class="row-grid"><section class="panel"><div class="section-head"><h2>${t('recent')}</h2><button class="card-link" data-action="records">${t('viewAll')} →</button></div>${recordTable()}</section>${notes()}</div>`:page==='records'?`<section class="panel"><div class="section-head"><div><h2>${t('records')}</h2><p>${t('recordsSub')}</p></div><div class="small-actions" style="margin:0">${button('csv','exportCSV','',readings().length?'':'disabled')}${button('backup','backup','',demo?'disabled':'')}${button('restore','restore','',demo?'disabled':'')}</div></div>${recordTable(5000)}<p>${t('localNote')}</p></section>`:page==='guide'?guidePage():devicePage()}<footer class="footer"><div>© YPET SAFE · Temperature studio<br>${t('clinicalNote')}</div><div>${t('local')} · ${t('keepLocal')}<br><a href="index.html?v=20261027-vitals1${lang!=='ko'?'&lang='+lang:''}">${t('home')} ↗</a></div></footer></main>`;}
function localNow(){const d=new Date(Date.now()-new Date().getTimezoneOffset()*60000);return d.toISOString().slice(0,16);}
function wireDialog(dialog){dialog.querySelectorAll('.field').forEach((field,i)=>{const input=field.querySelector('input,select,textarea'),label=field.querySelector('label');if(input&&label){if(!input.id)input.id=dialog.id+'-field-'+i;label.htmlFor=input.id;}});}
function openPet(edit=false){const p=edit?pet():null;const dialog=$('pet-dialog');dialog.innerHTML=`<button class="close-dialog" data-close aria-label="${t('cancel')}">×</button><h2>${t(edit?'editPet':'addPet')}</h2><p>${t('emptyIntro')}</p><form id="pet-form"><div class="field"><label for="dog-name">${t('name')}</label><input id="dog-name" name="name" maxlength="40" required value="${esc(p?.name||'')}" autocomplete="off"></div><div class="field"><label>${t('chipId')}</label><input name="chip" inputmode="numeric" pattern="[0-9]{15}" maxlength="15" value="${esc(p?.chip||'')}" placeholder="410160013062124"></div><div class="field-row"><div class="field"><label>${t('baseline')}</label><input name="baseline" type="number" min="30" max="45" step="0.1" value="${p?.baseline??''}"></div><div class="field"><label>${t('threshold')}</label><input name="threshold" type="number" min="0.2" max="2" step="0.1" required value="${p?.threshold||.5}"></div></div><p>${t('baselineHint')}</p><div class="alert-box">${t('healthBaselineBody')}</div><div class="dialog-actions"><button class="button" type="button" data-close>${t('cancel')}</button><button class="button primary" type="submit">${t('save')}</button></div></form>`;
 dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.target,chip=f.chip.value.trim(),name=f.elements.namedItem('name').value.trim();if(!name||chip&&db().pets.some(other=>other.id!==p?.id&&other.chip===chip)){toast(t('confirmChip'));return;}const next=clone(db());const data={id:p?.id||uid(),name,chip:chip||null,baseline:f.baseline.value===''?null:Number(f.baseline.value),threshold:Number(f.threshold.value)};if(p)next.pets[next.pets.findIndex(v=>v.id===p.id)]=data;else next.pets.push(data);if(persist(next)){selected=data.id;dialog.close();render();toast(t('saved'));}};wireDialog(dialog);dialog.showModal();}
function openReading(){if(!pet()){toast(t('addFirst'));return;}const dialog=$('reading-dialog');dialog.innerHTML=`<button class="close-dialog" data-close aria-label="${t('cancel')}">×</button><h2>${t('saveReading')}</h2><p>${esc(pet().name)} · ${t('clinicalNote')}</p><form><div class="field"><label>${t('method')}</label><select name="method"><option value="rectal">${t('rectal')}</option><option value="chip">${t('manualChip')}</option></select></div><div class="field-row"><div class="field"><label>${t('temperature')} (°C)</label><input name="temp" type="number" min="20" max="45" step="0.1" required placeholder="38.5"></div><div class="field"><label>${t('context')}</label><select name="context"><option value="rest">${t('rest')}</option><option value="activity">${t('activity')}</option><option value="other">${t('other')}</option></select></div></div><div class="field"><label>${t('receiptTime')}</label><input name="time" type="datetime-local" required value="${localNow()}"></div><div class="field"><label>${t('note')}</label><textarea name="note" maxlength="300"></textarea></div><p>${t('methodNote')}</p><div class="dialog-actions"><button class="button" type="button" data-close>${t('cancel')}</button><button class="button primary" type="submit">${t('save')}</button></div></form>`;
 dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.target,temp=Number(f.temp.value),date=new Date(f.time.value);if(!Number.isFinite(temp)||temp<20||temp>45||!Number.isFinite(date.getTime())||date.getTime()>Date.now()+300000||f.elements.namedItem('method').value==='chip'&&(temp<30||temp>45)){toast(t('invalidReading'));return;}if(saveRecord({id:uid(),petId:selected,temp,method:f.elements.namedItem('method').value,time:date.toISOString(),source:'manual',context:f.context.value,note:f.note.value.trim(),symptoms:clone(symptoms)})){method=f.elements.namedItem('method').value;dialog.close();render();toast(t('saved'));}};wireDialog(dialog);dialog.showModal();}
function saveRecord(record){const next=clone(db());if(next.records.length>=MAX){toast(t('limit'));return false;}next.records.push(record);return persist(next);}
function demoStart(){if(connected)device.gatt.disconnect();demo=true;const now=Date.now(),p={id:'demo-dubu',name:lang==='ko'?'두부':lang==='vi'?'Dubu (mẫu)':'Dubu',chip:'410160013062124',baseline:38.0,threshold:.5};demoDB={format:'ypet-vitals-v1',pets:[p],records:[]};const values=[37.9,38.0,38.1,38.0,37.8,37.9,38.0,38.1,38.2,38.0,37.9,38.0,38.1,38.2,38.0,37.9,38.0,38.1,38.3,38.1,38.0,38.2,38.1,38.0,38.1,38.2,38.1,38.2];values.forEach((temp,i)=>demoDB.records.push({id:'demo-chip-'+i,petId:p.id,temp,method:'chip',source:'ble',time:new Date(now-(values.length-1-i)*5*3600000).toISOString(),chip:p.chip,note:''}));[38.4,38.6,38.7,39.4,38.9,38.6,38.5].forEach((temp,i)=>demoDB.records.push({id:'demo-rectal-'+i,petId:p.id,temp,method:'rectal',source:'manual',time:new Date(now-(7-i)*19*3600000).toISOString(),note:''}));selected=p.id;method='chip';pending=null;page='dashboard';render();}
async function connect(){if(demo){toast(t('demoNoBle'));return;}if(!pet()){toast(t('addFirst'));return;}if(!window.isSecureContext||!navigator.bluetooth){toast(t('unsupported'));page='scanner';render();return;}connecting=true;render();try{device=await navigator.bluetooth.requestDevice({filters:[{namePrefix:'SC400'}],optionalServices:['3a95e1b9-d1a2-4876-8335-02108039b3a2']});device.addEventListener('gattserverdisconnected',onDisconnected);const server=await device.gatt.connect();const service=await server.getPrimaryService('3a95e1b9-d1a2-4876-8335-02108039b3a2');const chars=await service.getCharacteristics();stream=new SC400Codec.Stream();lastPacket={hex:'',time:0};for(const ch of chars){if(ch.properties.notify||ch.properties.indicate){ch.addEventListener('characteristicvaluechanged',received);subscriptions.push(ch);await ch.startNotifications();}}if(!subscriptions.length)throw Error('no-notify');connected=true;toast(t('connected'));}catch(error){if(device?.gatt?.connected)device.gatt.disconnect();toast(error.name==='NotFoundError'?t('cancelled'):t('connectError'));}finally{connecting=false;render();}}
function onDisconnected(){subscriptions.forEach(ch=>ch.removeEventListener('characteristicvaluechanged',received));subscriptions=[];connected=false;connecting=false;stream=new SC400Codec.Stream();render();toast(t('reconnect'));}
function received(event){const value=event.target.value,bytes=new Uint8Array(value.buffer,value.byteOffset,value.byteLength);rawLog.push({time:new Date().toISOString(),hex:Array.from(bytes).map(v=>v.toString(16).padStart(2,'0').toUpperCase()).join('-')});if(rawLog.length>100)rawLog.shift();const frames=stream.push(bytes);if(!frames.length){if(page==='scanner')render();return;}for(const frame of frames){const now=Date.now();if(frame.hex===lastPacket.hex&&now-lastPacket.time<2500)continue;lastPacket={hex:frame.hex,time:now};const match=state.pets.find(p=>p.chip===frame.chip);if(match)selected=match.id;pending={...frame,time:new Date(now).toISOString(),method:'chip',source:'ble'};if(frame.sensorInRange&&match){if(saveRecord({id:uid(),petId:match.id,temp:frame.temp,time:pending.time,method:'chip',source:'ble',chip:frame.chip,deviceTime:frame.deviceTime,hex:frame.hex,note:'',symptoms:clone(symptoms)})){method='chip';pending=null;toast(t('saved'));}}}render();}
function bindPending(){const p=pet();if(!p||!pending)return;if(p.chip&&p.chip!==pending.chip){toast(t('mismatch'));return;}if(!pending.sensorInRange){toast(t('invalidReading'));return;}if(!confirm(t('newChip')))return;const next=clone(db());if(next.records.length>=MAX){toast(t('limit'));return;}const item=next.pets.find(v=>v.id===p.id);item.chip=pending.chip;next.records.push({id:uid(),petId:p.id,temp:pending.temp,time:pending.time,method:'chip',source:'ble',chip:pending.chip,deviceTime:pending.deviceTime,hex:pending.hex,note:'',symptoms:clone(symptoms)});if(persist(next)){pending=null;method='chip';render();toast(t('saved'));}}
function exportCsv(){const data=readings().map(r=>[pet()?.name,r.time,r.temp,r.method,r.source,r.chip||'',r.note||'']);const safe=value=>{let s=String(value??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const csv=[['dog','time_iso','temperature_c','method','source','chip','note'],...data].map(row=>row.map(safe).join(',')).join('\r\n');download('\uFEFF'+csv,'ypet-readings.csv','text/csv;charset=utf-8');}
root.addEventListener('click',event=>{const del=event.target.closest('[data-delete]');if(del){if(confirm(t('removeReading'))){const next=clone(db());next.records=next.records.filter(r=>r.id!==del.dataset.delete);if(persist(next))render();}return;}const periodButton=event.target.closest('[data-period]');if(periodButton){period=periodButton.dataset.period;render();return;}const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;if(['dashboard','records','guide','scanner'].includes(action)){page=action;render();return;}if(action==='addPet')openPet();if(action==='editPet'&&pet())openPet(true);if(action==='manual')openReading();if(action==='demo')demoStart();if(action==='demoExit'){demo=false;demoDB=null;selected=state.pets[0]?.id||'';symptoms={breathing:false,collapse:false,gums:false};pending=null;render();}if(action==='connect')connect();if(action==='disconnect')device?.gatt?.disconnect();if(action==='bind')bindPending();if(action==='dismiss'){pending=null;render();}if(action==='backup')download(JSON.stringify(state,null,2),'ypet-vitals-backup-'+new Date().toISOString().slice(0,10)+'.json');if(action==='restore')$('restore-file').click();if(action==='csv')exportCsv();if(action==='raw')download(JSON.stringify({format:'SC400 raw reception',sampleVerifiedDecoder:true,checksumVerified:false,packets:rawLog},null,2),'sc400-raw-log.json');});
root.addEventListener('change',event=>{const e=event.target;if(e.id==='pet-choice'){selected=e.value;method=readings().at(-1)?.method||'chip';pending=null;symptoms={breathing:false,collapse:false,gums:false};render();}if(e.id==='method-choice'){method=e.value;render();}if(e.dataset.symptom){symptoms[e.dataset.symptom]=e.checked;render();}});
$('restore-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('large');const value=JSON.parse(await file.text());if(!VitalsModel.validateBackup(value))throw Error('invalid');if(!confirm(t('restoreConfirm')))return;const wasError=loadError;loadError=false;if(!persist(value)){loadError=wasError;return;}demo=false;selected=state.pets[0]?.id||'';pending=null;render();toast(t('saved'));}catch(error){toast(t('invalidBackup'));}finally{event.target.value='';}});
document.addEventListener('click',event=>{const choice=event.target.closest('[data-language-choice]');if(choice)requestAnimationFrame(()=>{const next=['en','vi'].includes(document.documentElement.lang)?document.documentElement.lang:'ko';if(next!==lang)render();});});
method=readings().at(-1)?.method||'chip';render();if(loadError)toast(t('storageError'));
})();
